	@Test
	void frameChainRestoresIndependentRegistriesAroundADomainlessBarrier() {
		try (BindingFrameReplay.Invocation first = new BindingFrameReplay.Invocation(DefaultCollectionFactory::new,
				null);
				BindingFrameReplay.Invocation second = new BindingFrameReplay.Invocation(DefaultCollectionFactory::new,
						null)) {
			BindingFrameBindings.Scope firstOwner = new BindingFrameBindings.Scope();
			BindingFrameBindings.Scope secondOwner = new BindingFrameBindings.Scope();
			BindingFrame parent = new BindingFrame(firstOwner, null, Map.of("outer", SEED), false, first.root);
			BindingFrame barrier = new BindingFrame(null, parent, Map.of(), true, null);
			BindingFrame top = new BindingFrame(secondOwner, barrier, Map.of("inner", SEED), false, second.root);
			List<BindingFrame> visited = new ArrayList<>();
			BindingFrameBindings.visitFrameChain(top, visited::add);
			assertThat(visited).containsExactly(top, barrier, parent);
			BindingFrame firstAnchor = BindingFrameBindings.replayAnchor(parent);
			BindingFrame secondAnchor = BindingFrameBindings.replayAnchor(top);
			BindingFrame serialized = copy(top);
			BindingFrame restored = BindingFrameBindings.restoreFrameChain(serialized,
					Arrays.asList(secondAnchor, null, firstAnchor).iterator());
			assertThat(restored.replay).isSameAs(second.root);
			assertThat(restored.replayIdentity).isEqualTo(serialized.replayIdentity);
			assertThat(restored.owner).isEqualTo(secondOwner);
			assertThat(restored.probe(secondOwner, "inner")).isEqualTo(SEED)
					.isSameAs(serialized.probe(secondOwner, "inner"));
			assertThat(restored.parent.isolatesProbes).isTrue();
			assertThat(restored.parent.replay).isNull();
			assertThat(restored.parent.replayIdentity).isNull();
			assertThat(restored.parent.parent.replay).isSameAs(first.root);
			assertThat(restored.parent.parent.owner).isEqualTo(firstOwner);
			assertThat(restored.parent.parent.probe(firstOwner, "outer")).isEqualTo(SEED);
			assertThat(BindingFrameBindings.restoreFrameChain(top,
					Arrays.<BindingFrame>asList(null, null, null).iterator())).isSameAs(top);
			assertThatThrownBy(() -> BindingFrameBindings.restoreFrameChain(serialized,
					List.of(secondAnchor).iterator())).isInstanceOf(IllegalArgumentException.class);
			assertThatThrownBy(() -> BindingFrameBindings.restoreFrameChain(serialized,
					Arrays.asList(secondAnchor, null, firstAnchor, secondAnchor).iterator()))
							.isInstanceOf(IllegalArgumentException.class);
		}
	}

