	private static BindingFrame deepChain(List<BindingFrameBindings.Scope> owners) {
		BindingFrame chain = null;
		for (int index = 0; index < 10_000; index++) {
			BindingFrameBindings.Scope owner = new BindingFrameBindings.Scope();
			owners.add(owner);
			Value value = SimpleValueFactory.getInstance().createLiteral(index);
			chain = new BindingFrame(owner, chain, Map.of("probe", value), false, null);
		}
		return chain;
	}

	private static void assertDeepChain(BindingFrame chain, List<BindingFrameBindings.Scope> owners) {
		for (int index = owners.size() - 1; index >= 0; index--) {
			assertThat(chain).as("frame %s", index).isNotNull();
			assertThat(chain.owner).as("owner %s", index).isEqualTo(owners.get(index));
			assertThat(chain.probe(owners.get(index), "probe"))
					.as("probe %s", index)
					.isEqualTo(SimpleValueFactory.getInstance().createLiteral(index));
			chain = chain.parent;
		}
		assertThat(chain).isNull();
	}

