	@Test
	void deepOrdinaryJoinPartitioningDoesNotRevisitEveryDescendantAtEachEdge() {
		int depth = 256;
		AtomicInteger childVisits = new AtomicInteger();
		List<TupleExpr> nodes = new ArrayList<>();
		TupleExpr root = new SingletonSet();
		nodes.add(root);
		for (int index = 0; index < depth; index++) {
			TupleExpr right = new SingletonSet();
			root = new CountingJoin(root, right, childVisits);
			nodes.add(right);
			nodes.add(root);
		}
		QueryEvaluationUtility.withQuerySafetySnapshot(root, () -> {
			childVisits.set(0);
			for (TupleExpr node : nodes) {
				assertThat(BindingFrameReplay.independentRegion(node)).isFalse();
			}
			assertThat(childVisits.get()).as("one lazy analysis may visit each join once").isLessThanOrEqualTo(depth);
			int afterPreparation = childVisits.get();
			for (TupleExpr node : nodes) {
				assertThat(BindingFrameReplay.independentRegion(node)).isFalse();
			}
			assertThat(childVisits.get()).as("prepared facts require no further subtree traversal")
					.isEqualTo(afterPreparation);
			return null;
		});
	}

	@Test
	void lazyReplayRetainsRowsThroughSerializationAndClosesProducerAndFactoryOnce() {
		AtomicInteger opened = new AtomicInteger();
		AtomicInteger closed = new AtomicInteger();
		AtomicInteger factoriesClosed = new AtomicInteger();
		BindingFrameReplay.Invocation invocation = new BindingFrameReplay.Invocation(
				() -> new DefaultCollectionFactory() {
					@Override
					public <K, V> Map<K, V> createMap() {
						return new SerializingMap<>();
					}

					@Override
					public void close() {
						factoriesClosed.incrementAndGet();
					}
				}, null);
		BindingSet input = BindingFrameBindings.push(new BindingFrameBindings.Scope(), EmptyBindingSet.getInstance(),
				row(SEED), CONTEXT, invocation.root);
		QueryEvaluationStep leaf = bindings -> {
			opened.incrementAndGet();
			return new LookAheadIteration<>() {
				private int position;
				private final QueryBindingSet reused = new QueryBindingSet(bindings);

				@Override
				protected BindingSet getNextElement() {
					if (++position > 2) {
						return null;
					}
					reused.setBinding("value", SimpleValueFactory.getInstance().createLiteral(position));
					return reused;
				}

				@Override
				protected void handleClose() {
					closed.incrementAndGet();
				}
			};
		};
		QueryEvaluationStep replay = BindingFrameReplay.region(new SingletonSet(), leaf, CONTEXT);
		try (CloseableIteration<BindingSet> first = replay.evaluate(input)) {
			assertThat(first.next().getValue("value")).isEqualTo(SimpleValueFactory.getInstance().createLiteral(1));
		}
		assertThat(closed).hasValue(0);
		List<Value> values = new ArrayList<>();
		try (CloseableIteration<BindingSet> second = replay.evaluate(input)) {
			while (second.hasNext()) {
				BindingSet result = second.next();
				values.add(result.getValue("value"));
				assertThat(BindingFrameBindings.probeValue(result, "seed")).isEqualTo(SEED);
				assertThat(result.getValue("seed")).isNull();
			}
		}
		invocation.finish();
		invocation.close();
		invocation.close();
		assertThat(values).containsExactly(SimpleValueFactory.getInstance().createLiteral(1),
				SimpleValueFactory.getInstance().createLiteral(2));
		assertThat(opened).hasValue(1);
		assertThat(closed).hasValue(1);
		assertThat(factoriesClosed).hasValue(1);
	}

