	@Test
	void replayDoesNotRestrictIndependentValuesToTheFirstCaller() {
		Value first = SimpleValueFactory.getInstance().createLiteral("first");
		Value second = SimpleValueFactory.getInstance().createLiteral("second");
		Value conflicting = SimpleValueFactory.getInstance().createLiteral("conflicting");
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingSets(List.of(row(first), row(second), row(second)));
		AtomicInteger opened = new AtomicInteger();
		QueryEvaluationStep valuesStep = new BindingSetAssignmentQueryEvaluationStep(values, CONTEXT);
		QueryEvaluationStep producer = input -> {
			opened.incrementAndGet();
			return valuesStep.evaluate(input);
		};
		try (BindingFrameReplay.Invocation invocation = new BindingFrameReplay.Invocation(DefaultCollectionFactory::new,
				null)) {
			QueryEvaluationStep replay = BindingFrameReplay.region(values, producer, CONTEXT);
			BindingSet firstInput = BindingFrameBindings.withReplay(row(first), invocation.root, CONTEXT);
			BindingSet secondInput = BindingFrameBindings.withReplay(row(second), invocation.root, CONTEXT);
			BindingSet missingInput = BindingFrameBindings.withReplay(EmptyBindingSet.getInstance(), invocation.root,
					CONTEXT);
			BindingSet conflictingInput = BindingFrameBindings.withReplay(row(conflicting), invocation.root, CONTEXT);
			assertThat(replayRows(replay, firstInput)).extracting(row -> row.getValue("seed")).containsExactly(first);
			assertThat(replayRows(replay, secondInput)).extracting(row -> row.getValue("seed"))
					.containsExactly(second, second);
			assertThat(replayRows(replay, missingInput)).extracting(row -> row.getValue("seed"))
					.containsExactly(first, second, second);
			assertThat(replayRows(replay, conflictingInput)).isEmpty();
			assertThat(replayRows(replay, firstInput)).extracting(row -> row.getValue("seed")).containsExactly(first);
			assertThat(opened).hasValue(1);
		}
	}

	@Test
	void replayRetainsDistinctCallersAndDuplicateIndependentRows() {
		Value first = SimpleValueFactory.getInstance().createLiteral("first");
		Value second = SimpleValueFactory.getInstance().createLiteral("second");
		QueryBindingSet independent = new QueryBindingSet();
		independent.addBinding("result", SEED);
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingSets(List.of(independent, independent));
		AtomicInteger opened = new AtomicInteger();
		QueryEvaluationStep valuesStep = new BindingSetAssignmentQueryEvaluationStep(values, CONTEXT);
		try (BindingFrameReplay.Invocation invocation = new BindingFrameReplay.Invocation(DefaultCollectionFactory::new,
				null)) {
			QueryEvaluationStep replay = BindingFrameReplay.region(values, input -> {
				opened.incrementAndGet();
				return valuesStep.evaluate(input);
			}, CONTEXT);
			BindingSet firstInput = BindingFrameBindings.withReplay(row(first), invocation.root, CONTEXT);
			BindingSet secondInput = BindingFrameBindings.withReplay(row(second), invocation.root, CONTEXT);
			BindingSet missingInput = BindingFrameBindings.withReplay(EmptyBindingSet.getInstance(), invocation.root,
					CONTEXT);
			assertThat(replayRows(replay, firstInput)).extracting(row -> row.getValue("seed"))
					.containsExactly(first, first);
			List<BindingSet> secondRows = replayRows(replay, secondInput);
			assertThat(secondRows).extracting(row -> row.getValue("seed")).containsExactly(second, second);
			assertThat(secondRows).allSatisfy(row -> assertThat(row.getValue("result")).isEqualTo(SEED));
			assertThat(replayRows(replay, missingInput))
					.allSatisfy(row -> assertThat(row.hasBinding("seed")).isFalse());
			assertThat(opened).hasValue(1);
		}
	}

	@ParameterizedTest(name = "nested triple={0}")
	@ValueSource(booleans = { false, true })
	void compatibleReplayPrefersTheCurrentCallerAuthority(boolean nested) {
		Value plain = authorityValue(nested, false);
		Value trusted = authorityValue(nested, true);
		assertThat(plain).isEqualTo(trusted).isNotSameAs(trusted);
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingSets(List.of(row(plain)));
		QueryEvaluationStep valuesStep = new BindingSetAssignmentQueryEvaluationStep(values, CONTEXT);
		try (BindingFrameReplay.Invocation invocation = new BindingFrameReplay.Invocation(DefaultCollectionFactory::new,
				null)) {
			BindingSet caller = BindingFrameBindings.withReplay(row(trusted), invocation.root, CONTEXT);
			BindingSet result = replayRows(BindingFrameReplay.region(values, valuesStep, CONTEXT), caller).getFirst();
			assertThat(result.getValue("seed")).isSameAs(trusted);
		}
	}

